S = "Hakeem Force Academy"
QS = [
 (S, "Convert 90 degrees into radians.", ["pi/4", "pi/3", "pi/2", "pi"], 2,
  "1 degree = pi/180 radian. So 90 degrees = 90 x pi/180 = pi/2 radians.", "A full circle of 360 degrees equals 2 pi radians.", [349, 3108, 704, 2452]),
 (S, "If the diameter of a circle is 56, what is its radius?", ["28", "112", "56", "14"], 0,
  "Radius is half of the diameter. 56 / 2 = 28.", "Diameter = 2 x radius.", [396]),
 (S, "What is the diameter of a circle whose radius is 56?", ["28", "112", "168", "56"], 1,
  "Diameter is twice the radius. 2 x 56 = 112.", "The circumference of a circle is pi times the diameter.", [2877]),
 (S, "Which pamphlet was written by Choudhry Rahmat Ali in 1933?", ["Now or Never", "The Muslim Question", "Pakistan Resolution", "Our Struggle"], 0,
  "Choudhry Rahmat Ali wrote the pamphlet Now or Never: Are We to Live or Perish Forever?", "In this pamphlet he first proposed the name Pakistan.", [877]),
 (S, "Which uncle brought up the Holy Prophet (PBUH) after the death of his grandfather Abdul Muttalib?", ["Hazrat Hamza", "Abu Lahab", "Hazrat Abbas", "Abu Talib"], 3,
  "After Abdul Muttalib died, the Prophet (PBUH) was looked after by his uncle Abu Talib.", "Abu Talib was the father of Hazrat Ali (RA).", [3334]),
 (S, "Ramiz Raja was a famous player of which game?", ["Hockey", "Cricket", "Squash", "Football"], 1,
  "Ramiz Raja played for Pakistan in Tests and ODIs from 1984 to 1997.", "He was later the PCB chairman (2021 to 2022) and is a well known commentator.", [2367]),
 (S, "In which province are the Ras Koh Hills located?", ["Punjab", "Sindh", "Khyber Pakhtunkhwa", "Balochistan"], 3,
  "The Ras Koh Hills lie in Chagai district of Balochistan.", "Pakistan carried out its nuclear tests of May 1998 in the Chagai area.", [3550]),
 (S, "What is the meaning of the word rash?", ["Careful", "Slow", "Hasty and reckless", "Calm"], 2,
  "As an adjective, rash means acting without thinking about the results, so hasty and reckless.", "As a noun, rash also means red spots on the skin.", [451, 3005]),
 (S, "What is the meaning of the idiom 'smell a rat'?", ["To suspect that something is wrong", "To be very hungry", "To find a lost thing", "To feel very happy"], 0,
  "The idiom means to sense that something is dishonest or wrong.", "The idiom is used when a person becomes suspicious of a plan or person.", [3014, 3015]),
 (S, "What type of number is 11/7?", ["Irrational number", "Rational number", "Imaginary number", "Not a real number"], 1,
  "11/7 is a ratio of two integers with a non-zero denominator, so it is rational (and also real).", "Every rational number is also a real number.", [2230]),
 (S, "What type of number is 7/11?", ["Irrational number", "Imaginary number", "Rational number", "Prime number"], 2,
  "7/11 is written as p/q with integers p and q and q not zero, so it is rational.", "Its decimal form 0.636363... is repeating.", [2233]),
 (S, "What type of number is 7/9?", ["Rational number", "Irrational number", "Imaginary number", "Natural number"], 0,
  "7/9 is a ratio of two integers, so it is a rational number.", "Its decimal form 0.777... repeats forever.", [270]),
 (S, "What is a rational number?", ["A number that cannot be written as a fraction", "A number that can be written as p/q where p and q are integers and q is not zero", "A number with a non-repeating infinite decimal", "A number that is only positive"], 1,
  "A rational number is any number that can be expressed as the ratio p/q of two integers with q not equal to 0.", "Terminating and repeating decimals are rational numbers.", [2651]),
 (S, "How many rational numbers lie between 0 and 1?", ["Only 10", "None", "Infinitely many", "Only 100"], 2,
  "Between any two rational numbers there is another one, for example their average, so the set between 0 and 1 is infinite.", "Examples are 1/2, 1/3, 2/5 and 3/4.", [3143]),
 (S, "In the complex number 7 - 2i, which part is the real part?", ["-2", "2", "7", "-2i"], 2,
  "A complex number a + bi has real part a. Here a = 7 and the imaginary part is -2.", "The letter i stands for the square root of -1.", [753]),
 (S, "If the letters of the word UEAYTB are rearranged to make a meaningful word, what is the last letter of that word?", ["B", "Y", "T", "U"], 1,
  "The letters make the word BEAUTY, whose last letter is Y.", "BEAUTY has six letters including three vowels.", [2377]),
 (S, "Rearrange the letters of CHIKARA to make the name of a city. Which city is it?", ["Karachi", "Lahore", "Quetta", "Multan"], 0,
  "The letters C H I K A R A can be arranged to spell KARACHI.", "Karachi is the largest city of Pakistan.", [2376]),
 (S, "Muammar Gaddafi was the long-time ruler of which country?", ["Egypt", "Iraq", "Libya", "Syria"], 2,
  "Muammar Gaddafi ruled Libya from 1969 until he was overthrown in 2011.", "He was killed in October 2011 during the Libyan civil war.", [1615]),
 (S, "What was the immediate cause of the Second World War in 1939?", ["The attack on Pearl Harbor", "The German invasion of Poland", "The fall of France", "The Russian Revolution"], 1,
  "Germany invaded Poland on 1 September 1939, and Britain and France then declared war on Germany.", "The Treaty of Versailles and the rise of dictators are seen as the deeper causes.", [3342, 3343]),
 (S, "What is the meaning of the word reasonable?", ["Foolish", "Angry", "Sensible and fair", "Unfair"], 2,
  "Reasonable means having good sense and being fair. Its synonym is sensible.", "The opposite word is unreasonable.", [981, 3193]),
 (S, "What was the character of the Holy Prophet (PBUH) according to Hazrat Aisha (RA)?", ["Like the Holy Quran", "Like a king", "Like a warrior only", "Like a trader"], 0,
  "When asked about his character, Hazrat Aisha (RA) replied that his character was the Quran.", "This reply is reported in Sahih Muslim.", [622]),
 (S, "How many countries are strictly counted as Scandinavian countries?", ["2", "3", "5", "7"], 1,
  "Scandinavia strictly means Denmark, Norway and Sweden.", "The wider Nordic region also includes Finland and Iceland, making five countries.", [1696]),
 (S, "In which region of the world is Pakistan situated?", ["South Asia", "Central Asia", "East Asia", "Middle East"], 0,
  "Pakistan lies in South Asia together with India, Bangladesh, Nepal, Bhutan, Sri Lanka, the Maldives and Afghanistan.", "Pakistan is also a member of SAARC, the regional group of South Asia.", [2102]),
 (S, "According to most Pakistani textbooks, into how many physical regions is Pakistan divided?", ["4", "5", "6", "8"], 2,
  "The six regions are the Northern Mountains, Western Mountains, Balochistan Plateau, Potwar Plateau and Salt Range, Indus Plain and the Deserts.", "Some sources group the regions differently and give a different number.", [2226, 2227]),
 (S, "What was the relation of Hazrat Ali (RA) with the Holy Prophet (PBUH)?", ["Uncle", "Cousin and son-in-law", "Grandson", "Brother-in-law only"], 1,
  "Hazrat Ali (RA) was the son of Abu Talib, the Prophet's uncle, so he was his cousin. He married Hazrat Fatima (RA), so he was also his son-in-law.", "Hazrat Hasan and Hazrat Husain (RA) were their sons.", [3126]),
]
